used, out, missing = set(), [], []
for hub, art, rev, heads in A:
    s = n = 0
    for h in heads:
        if h in rows: s += int(rows[h]['head_rf_30d']) + int(rows[h]['tail_rf_sum']); n += int(rows[h]['phrases']); used.add(h)
        else: missing.append(h)
    out.append((hub, art, rev, s, n, ' | '.join(heads)))
out.sort(key=lambda r: -r[3])
with open(os.path.join(ROOT, 'seo', '03-karta-statej.csv'), 'w', newline='', encoding='utf-8') as f:
    w = csv.writer(f); w.writerow(['rank', 'hub', 'article', 'reviewer', 'demand_rf_30d', 'phrases', 'heads'])
    for i, r in enumerate(out, 1): w.writerow([i, *r])
left = [h for h in rows if h not in used]
print('статей:', len(out), '| кандидатов не распределено:', len(left), '| не найдено в z32:', missing)
